INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 14, 'theory', 'Квиз: постоянная настройка сети');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 0, 'Вы выполнили ip addr add 10.0.0.5/24 dev eth0, и после перезагрузки адреса нет. Почему?', '["Команда ip записывает адрес во временный файл в /tmp", "Адрес живёт только в состоянии ядра в памяти; постоянство дают файлы и служба вроде NetworkManager или networkd", "Адреса из ip удаляет cron при загрузке", "Адрес можно сохранить только командой ifconfig"]', 1, 'ip напрямую меняет состояние ядра, а при загрузке ядро пустое. Чтобы настройка вернулась, нужна служба, которая читает конфигурацию с диска.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 1, 'В /etc/netplan лежат 50-a.yaml с addresses: [10.0.0.5/24] и 60-b.yaml с addresses: [10.0.0.6/24] для одной карты. Что получится?', '["Останется только 10.0.0.6/24, поздний файл заменит список", "Останется только 10.0.0.5/24, первый файл главный", "Списки склеятся: у карты будут оба адреса", "Netplan откажется работать с двумя файлами"]', 2, 'Скаляры нетплан перезаписывает, а списки склеивает, новые элементы идут в конец старого. Заменить список целиком можно только положив тот же файл под тем же именем в каталог с более высоким приоритетом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 2, 'Интерфейсу подходят сразу два файла: 10-wired.network и 20-all.network. Что сделает systemd-networkd?', '["Объединит настройки обоих файлов", "Применит последний по алфавиту файл", "Выдаст ошибку о конфликте", "Применит только 10-wired.network, остальные проигнорирует"]', 3, 'Применяется первый по алфавитному порядку подошедший файл, остальные игнорируются, даже если подходят. Поэтому общие правила кладут в файлы с большим номером.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 3, 'Вы запустили netplan try по SSH, новая настройка оборвала сессию, и вы ничего не нажали. Что произойдёт?', '["Через таймаут (по умолчанию 120 секунд) конфигурация откатится сама", "Новая конфигурация останется навсегда", "Сервер перезагрузится", "Netplan будет ждать подтверждения бесконечно"]', 0, 'Если подтверждения нет за отведённое время, netplan try возвращает прежнюю конфигурацию. Поэтому его используют для удалённых правок; после отката проверьте, что сеть действительно вернулась.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 4, 'Вы положили профиль в /etc/NetworkManager/system-connections с правами 0644, а NetworkManager его не показывает. Что вероятнее всего?', '["Профиль нужно положить в /etc/sysconfig", "Файл доступен не только руту, и менеджер его игнорирует; нужны права 0600", "Менеджер читает файлы только после перезагрузки сервера", "Расширение файла обязательно должно быть .conf"]', 1, 'Профиль может содержать пароли, поэтому менеджер игнорирует файл, доступный кому-либо кроме рута. После правки прав и ручных изменений выполните nmcli connection reload.');
